export function increment(value: number): number {
  return value + 1;
}

export function decrement(value: number): number {
  return value - 1;
}

export function formatCount(value: number): string {
  return String(value);
}

export function splitNotes(text: string): string[] {
  return text.split("\n");
}

export function parseFlag(text: string): boolean | null {
  if (text === "true") {
    return true;
  }
  if (text === "false") {
    return false;
  }
  return null;
}

